contract InvMutTest {
    C c;

    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Single public function performing the test. Parameters: an Ether amount to attempt to wager.
    function run(uint256 betAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (betAmount)); require(betAmount <= 1000000000000000000000000000000);
        require(true);

        // Record balances and winnersPot before interactions
        uint256 beforeTesterBal = address(this).balance;
        uint256 beforeCbal = address(c).balance;
        uint256 beforeWinnersPot = c.winnersPot(); if (__ESBMC_reverted()) return;

        // Attempt to wager: must be a top-level call. If we don't have funds, this call will revert; capture via try/catch.
        bool wagerReverted;
        c.wager{value: betAmount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            wagerReverted = true;
        } else {
            wagerReverted = false;
        }

        // Attempt to call play(): top-level call; capture whether it reverted.
        bool playReverted;
        c.play(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            playReverted = true;
        } else {
            playReverted = false;
        }

        // Read balances and winnersPot after interactions
        uint256 afterTesterBal = address(this).balance;
        uint256 afterCbal = address(c).balance;
        uint256 afterWinnersPot = c.winnersPot(); if (__ESBMC_reverted()) return;

        // Assert the invariant: if play did not revert then winnersPot equals half of c's balance
        // and the tester's net gain is at most the previous contract half-pool plus the betAmount it sent (conservative upper bound).
        assert(playReverted || (afterWinnersPot == afterCbal / 2 && (afterTesterBal >= beforeTesterBal ? afterTesterBal - beforeTesterBal <= beforeCbal / 2 + betAmount : true)));
    }

    receive() external payable {}
}

