// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 0);
    }

    function _run(uint256 betAmount) internal {
        betAmount = bound(betAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(true);
        uint256 beforeTesterBal = address(this).balance;
        uint256 beforeCbal = address(c).balance;
        uint256 beforeWinnersPot;
        try c.winnersPot() returns (uint256 __r) { beforeWinnersPot = __r; } catch { return; }
        bool wagerReverted;
        try c.wager{value: betAmount}() {
            wagerReverted = false;
        } catch {
            wagerReverted = true;
        }
        bool playReverted;
        try c.play() {
            playReverted = false;
        } catch {
            playReverted = true;
        }
        uint256 afterTesterBal = address(this).balance;
        uint256 afterCbal = address(c).balance;
        uint256 afterWinnersPot;
        try c.winnersPot() returns (uint256 __r) { afterWinnersPot = __r; } catch { return; }
        assertTrue(playReverted || (afterWinnersPot == afterCbal / 2 && (afterTesterBal >= beforeTesterBal ? afterTesterBal - beforeTesterBal <= beforeCbal / 2 + betAmount : true)));
    }

    function testFuzz_run(uint256 betAmount) public {
        _run(betAmount);
    }

    receive() external payable {}
}
